package com.hrflow.platform.email;
import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class EmailService { private final JavaMailSender mail; @Value("${hrflow.mail.from:HRFlow <no-reply@hrflow.local>}")String from; @Value("${hrflow.frontend-base-url:http://localhost:4200}")String frontend;
 public void verification(String email,String token){send(email,"Vérifiez votre adresse HRFlow","Bienvenue sur HRFlow. Vérifiez votre adresse : "+frontend+"/verify-email?token="+token);} public void reset(String email,String token){send(email,"Réinitialisation du mot de passe HRFlow","Réinitialisez votre mot de passe : "+frontend+"/reset-password?token="+token);} private void send(String to,String subject,String text){SimpleMailMessage m=new SimpleMailMessage();m.setFrom(from);m.setTo(to);m.setSubject(subject);m.setText(text);mail.send(m);}}
